            <div className="bg-white dark:bg-zinc-950">
              <AgendaView
                key={`${currentDate.toISOString()}-${refreshKey}`}
                refreshKey={refreshKey}
                date={currentDate}
                courtCount={COURT_COUNT}
              />
            </div>
          </BentoCard>
        </TabsContent>

        <TabsContent value="history" className="mt-0 outline-none">
          <ReservationHistory onViewInCalendar={handleViewInCalendar} />
        </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/context/auth-context";
import { deleteSaleAction } from "@/lib/actions/sales";
import { formatPrice } from "@/lib/currency";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import {
  Loader2,
  PlusCircle,
  AlertTriangle,
  MoreVertical,
  Trash2,
  ShoppingCart,
  Receipt,
  User,
  Calendar,
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import { PageHeader } from "@/components/layout/page-header";
import { BentoCard } from "@/components/ui/bento-card";
import { cn } from "@/lib/utils";

interface SalesClientProps {
  initialSales: any[];
  initialMembers: any[];
  showPageHeader?: boolean;
}

export default function SalesClient({
  initialSales,
  initialMembers,
  showPageHeader = true,
}: SalesClientProps) {
  const router = useRouter();
  const { idToken } = useAuth();

  const [sales, setSales] = useState<any[]>(initialSales);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    setSales(initialSales);
  }, [initialSales]);

  const memberMap = useMemo(() => {
    if (!initialMembers) return new Map();
    return new Map(
      initialMembers.map((member) => [
        member.id,
        `${member.firstName} ${member.lastName}`,
      ])
    );
  }, [initialMembers]);

  const salesWithMemberNames = useMemo(() => {
    return sales.map((sale) => {
      let memberName = "Външен клиент";
      if (sale.memberId === "GUEST_EXTERNAL") {
        memberName = "Външен гост";
      } else if (sale.memberId && sale.memberId !== "Walk-in Customer") {
        memberName = memberMap.get(sale.memberId) || "Неизвестен член";
      }
      return {
        ...sale,
        memberName,
      };
    });
  }, [sales, memberMap]);

  const sortedSales = useMemo(() => {
    return [...salesWithMemberNames].sort((a, b) => {
      if (a.status === "pending" && b.status !== "pending") return -1;
      if (a.status !== "pending" && b.status === "pending") return 1;
      return new Date(b.saleDate).getTime() - new Date(a.saleDate).getTime();
    });
  }, [salesWithMemberNames]);

  const handleRowClick = (saleId: string) => {
    router.push(`/sales/${saleId}/receipt`);
  };

  const handleDelete = async () => {
    if (!saleToDelete || !idToken) return;
    setIsDeleting(true);

    const originalSales = [...sales];
    // Оптимистично изтриване от UI
    const updatedSales = sales.filter((s) => s.id !== saleToDelete);
    setSales(updatedSales);

    try {
      const result = await deleteSaleAction(saleToDelete, idToken);
      if (result.success) {
        toast.success(result.message || "Продажбата беше изтрита успешно");
        router.refresh();
      } else {
        setSales(originalSales);
        toast.error(result.message || "Грешка при изтриване");
      }
    } catch (error) {
      setSales(originalSales);
      console.error("Error deleting sale:", error);
      toast.error("Грешка при изтриване");
    } finally {
      setIsDeleting(false);
      setSaleToDelete(null);
    }
  };

  const loading = false;
  const error = null;

  const renderTableContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center py-32 space-y-6">
          <Loader2
            className="h-10 w-10 animate-spin text-zinc-200"
            strokeWidth={1}
          />
          <p className="text-zinc-400 font-medium uppercase tracking-[0.3em] text-[10px]">
            Зареждане на продажби...
          </p>
        </div>
      );
    }
    
    if (error) {
      return (
        <div className="text-center py-32 text-rose-500 flex flex-col items-center">
          <AlertTriangle
            className="h-10 w-10 mb-6 opacity-30"
            strokeWidth={1}
          />
          <p className="text-sm font-light uppercase tracking-widest">
            {error || "An error occurred while loading the sales."}
          </p>
        </div>
      );
    }

    return (
      <div className="overflow-x-auto">
        <Table>
          <TableHeader className="bg-zinc-50/50">
            <TableRow className="border-none hover:bg-transparent h-16">
              <TableHead className="font-medium text-[10px] uppercase tracking-[0.2em] text-zinc-400 px-8">
                Дата и Час
              </TableHead>
              <TableHead className="font-medium text-[10px] uppercase tracking-[0.2em] text-zinc-400">
                Клиент
              </TableHead>
              <TableHead className="font-medium text-[10px] uppercase tracking-[0.2em] text-zinc-400">
                Статус
              </TableHead>
              <TableHead className="font-medium text-[10px] uppercase tracking-[0.2em] text-zinc-400 text-right pr-8">
                Сума
              </TableHead>
              <TableHead className="w-[80px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {sortedSales.length > 0 ? (
              sortedSales.map((sale) => (
                <TableRow
                  key={sale.id}
                  onClick={() => handleRowClick(sale.id)}
                  className="cursor-pointer group border-zinc-50 hover:bg-zinc-50/50 transition-colors h-20"
                >
                  <TableCell className="px-8">
                    <div className="flex items-center gap-3">
                      <Calendar
                        className="h-3.5 w-3.5 text-zinc-300"
                        strokeWidth={1.5}
                      />
                      <span className="text-sm font-light text-zinc-600">
                        {new Date(sale.saleDate).toLocaleString("bg-BG")}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <User
                        className="h-3.5 w-3.5 text-zinc-300"
                        strokeWidth={1.5}
                      />
                      <span className="text-sm font-medium text-zinc-900">
                        {sale.memberName}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge
                      className={cn(
                        "border-none rounded-full px-3 py-1 text-[9px] uppercase tracking-widest font-medium",
                        sale.isPaid
                          ? "bg-emerald-50 text-emerald-600"
                          : "bg-amber-50 text-amber-600"
                      )}
                    >
                      {sale.isPaid ? "Платено" : "Висящо"}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right font-medium text-sm text-zinc-950 pr-8 tabular-nums">
                    {formatPrice(sale.totalAmount)}
                  </TableCell>
                  <TableCell
                    className="text-right px-6"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-10 w-10 rounded-xl group-hover:bg-white group-hover:shadow-sm transition-all"
                        >
                          <MoreVertical className="h-4 w-4 text-zinc-300" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="end"
                        className="rounded-3xl shadow-2xl border-zinc-100 p-2 min-w-[160px]"
                      >
                        <DropdownMenuItem
                          className="text-rose-500 focus:bg-rose-50 focus:text-rose-600 cursor-pointer font-medium rounded-xl p-3"
                          onSelect={() => setSaleToDelete(sale.id)}
                        >
                          <Trash2
                            className="mr-3 h-4 w-4"
                            strokeWidth={1.5}
                          />
                          <span className="text-[11px] uppercase tracking-widest">
                            Изтрий
                          </span>
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={5} className="py-32 text-center">
                  <ShoppingCart
                    className="h-12 w-12 text-zinc-100 mx-auto mb-6"
                    strokeWidth={1}
                  />
                  <p className="text-zinc-400 font-medium uppercase tracking-[0.3em] text-[10px]">
                    Все още няма продажби
                  </p>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {showPageHeader ? (
        <>
          <PageHeader
            title="Продажби"
            description="Проследяване на продажби на инвентар, напитки и услуги в реално време."
            breadcrumbs={[
              { label: "Начало", href: "/dashboard" },
              { label: "Продажби" },
            ]}
          >
            <Button
              onClick={() => router.push("/sales/new")}
              className="rounded-xl shadow-none bg-zinc-950 text-white hover:bg-zinc-800 h-12 px-8 font-medium text-[11px] uppercase tracking-widest transition-all"
            >
              <PlusCircle className="mr-3 h-4 w-4" strokeWidth={1.5} /> Нова
              продажба
            </Button>
          </PageHeader>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <BentoCard className="p-8 bg-white border border-zinc-100 shadow-none rounded-4xl">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-3xl font-light tracking-tighter mb-2">
                    {sortedSales.length}
                  </p>
                  <p className="text-[10px] text-zinc-400 uppercase tracking-[0.2em]">
                    Общо транзакции
                  </p>
                </div>
                <ShoppingCart
                  className="h-5 w-5 text-zinc-300"
                  strokeWidth={1.5}
                />
              </div>
            </BentoCard>
            <BentoCard className="p-8 bg-white border border-zinc-100 shadow-none rounded-4xl">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-3xl font-light tracking-tighter text-amber-600 mb-2">
                    {sortedSales.filter((s) => !s.isPaid).length}
                  </p>
                  <p className="text-[10px] text-zinc-400 uppercase tracking-[0.2em]">
                    Висящи плащания
                  </p>
                </div>
                <AlertTriangle
                  className="h-5 w-5 text-amber-400"
                  strokeWidth={1.5}
                />
              </div>
            </BentoCard>
            <BentoCard className="md:col-span-2 p-8 flex items-center bg-zinc-950 text-white border-none shadow-none rounded-4xl">
              <div className="flex items-center gap-6">
                <div className="p-4 bg-white/5 rounded-2xl border border-white/5">
                  <Receipt className="h-6 w-6 text-primary" strokeWidth={1.5} />
                </div>
                <div>
                  <p className="text-zinc-500 uppercase tracking-[0.3em] text-[9px] mb-2">
                    Дневен оборот
                  </p>
                  <p className="text-xl font-light text-zinc-100 tracking-tight">
                    Преглед на приходите за деня
                  </p>
                </div>
              </div>
            </BentoCard>
          </div>
        </>
      ) : (
        <div className="flex justify-between items-center px-2 flex-wrap gap-4">
          <div>
            <h3 className="text-sm font-semibold uppercase tracking-wider text-zinc-900">
              Хроника на плащанията
            </h3>
            <p className="text-[11px] text-zinc-400">
              Преглед и управление на всички регистрирани плащания.
            </p>
          </div>
          <Button
            onClick={() => router.push("/sales/new")}
            className="rounded-xl shadow-none bg-zinc-950 text-white hover:bg-zinc-800 h-10 px-6 font-medium text-[10px] uppercase tracking-widest transition-all"
          >
            <PlusCircle className="mr-2 h-3.5 w-3.5" strokeWidth={1.5} /> Нова
            продажба
          </Button>
        </div>
      )}

      <BentoCard className="overflow-hidden border border-zinc-100 bg-white shadow-none rounded-5xl">
        {renderTableContent()}
      </BentoCard>

      <AlertDialog
        open={!!saleToDelete}
        onOpenChange={(open) => !open && setSaleToDelete(null)}
      >
        <AlertDialogContent className="rounded-5xl border-none shadow-2xl p-8">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-lg font-medium uppercase tracking-[0.2em] text-zinc-900">
              Сигурни ли сте?
            </AlertDialogTitle>
            <AlertDialogDescription className="text-sm font-light text-zinc-500 mt-4 leading-relaxed">
              Това действие ще изтрие записа на продажбата за постоянно. Ако
              това е продажба на инвентар, наличностите няма да се възстановят
              автоматично.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="mt-8 gap-3">
            <AlertDialogCancel className="rounded-xl border-zinc-100 h-12 px-6 font-medium text-[11px] uppercase tracking-widest hover:bg-zinc-50 transition-all">
              Отказ
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={isDeleting}
              className="bg-rose-500 text-white hover:bg-rose-600 rounded-xl h-12 px-8 font-medium text-[11px] uppercase tracking-widest shadow-none transition-all"
            >
              {isDeleting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Изтрий
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Image from "next/image";
import { BentoCard } from "@/components/ui/bento-card";
import { PageHeader } from "@/components/layout/page-header";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Settings,
  Shield,
  Palette,
  User,
  Save,
  Lock,
  Mail,
  Globe,
  Building2,
  Camera,
  CheckCircle2,
  Activity,
  Clock,
  Loader2,
  RefreshCw,
  MapPin,
  Phone,
  Users,
} from "lucide-react";
import {
  InstagramIcon,
  YoutubeIcon,
  FacebookIcon,
} from "@/components/icons/social-icons";
import { toast } from "react-hot-toast";
import { getAllSites, updateSite } from "@/services/site-service";
import { Site } from "@/types/site.types";
import { getAuditLogsAction } from "@/lib/actions/audit";
import { AuditLog } from "@/lib/audit-logger";

export default function SettingsClient() {
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [formData, setFormData] = useState<{
    [key: string]: Partial<Site>;
  }>({});
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [loadingLogs, setLoadingLogs] = useState(false);

  const fetchLogs = async () => {
    setLoadingLogs(true);
    try {
      const logs = await getAuditLogsAction(50);
      setAuditLogs(logs);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingLogs(false);
    }
  };

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const allSites = await getAllSites();

        // Initialize form data
        const initialFormData: { [key: string]: Partial<Site> } = {};
        allSites.forEach((site) => {
          initialFormData[site.id] = { ...site };
        });
        setFormData(initialFormData);
      } catch (error) {
        console.error("Error fetching settings:", error);
        toast.error("Грешка при зареждане на настройките.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchSettings();
    fetchLogs();
  }, []);

  const handleScheduleChange = (
    siteId: string,
    day: string,
    field: "open" | "close" | "isOpen",
    value: string | boolean
  ) => {
    setFormData((prev) => {
      const site = prev[siteId] || {};
      const sched = site.schedule || {
        monday: { open: "08:00", close: "22:00", isOpen: true },
        tuesday: { open: "08:00", close: "22:00", isOpen: true },
        wednesday: { open: "08:00", close: "22:00", isOpen: true },
        thursday: { open: "08:00", close: "22:00", isOpen: true },
        friday: { open: "08:00", close: "22:00", isOpen: true },
        saturday: { open: "08:00", close: "22:00", isOpen: true },
        sunday: { open: "08:00", close: "22:00", isOpen: true },
      };

      return {
        ...prev,
        [siteId]: {
          ...site,
          schedule: {
            ...sched,
            [day]: {
              ...sched[day as keyof typeof sched],
              [field]: value,
            },
          },
        },
      };
    });
  };

  const handleInventoryChange = (
    siteId: string,
    type: "compressors" | "legs" | "arms" | "hips",
    value: number
  ) => {
    setFormData((prev) => {
      const site = prev[siteId] || {};
      const inv = site.inventory || {
        attachments: { legs: 0, arms: 0, hips: 0 },
        compressors: 0,
      };
      const atts = inv.attachments || { legs: 0, arms: 0, hips: 0 };

      const newInv = { ...inv };
      if (type === "compressors") {
        newInv.compressors = value;
      } else {
        newInv.attachments = { ...atts, [type]: value };
      }

      return {
        ...prev,
        [siteId]: {
          ...site,
          inventory: newInv,
        },
      };
    });
  };

  const handleInputChange = (
    siteId: string,
    field: keyof Site,
    value: string
  ) => {
    setFormData((prev) => ({
      ...prev,
      [siteId]: {
        ...prev[siteId],
        [field]: value,
      },
    }));
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      // Save each site's settings
      const savePromises = Object.entries(formData).map(([id, data]) =>
        updateSite({ ...data, id })
      );

      await Promise.all(savePromises);

      toast.success("Настройките са запазени успешно!", {
        style: {
          borderRadius: "1.5rem",
          background: "#18181b",
          color: "#fff",
          fontWeight: 400,
          fontSize: "0.875rem",
        },
      });
    } catch (error) {
      console.error("Error saving settings:", error);
      toast.error("Грешка при запазване на настройките.");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] space-y-4">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
        <p className="text-zinc-500 font-light uppercase tracking-widest text-xs">
          Зареждане на настройки...
        </p>
      </div>
    );
  }

  const bkgData = formData["bkgalabovo"] || {};
  const rzData = formData["recoveryzone"] || {};

  const inputClass =
    "h-14 rounded-xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 text-sm font-light shadow-none focus-visible:ring-primary";
  const inputClassRz =
    "h-14 rounded-xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 text-sm font-light shadow-none focus-visible:ring-[#00f2fe]";
  const labelClass =
    "text-[11px] font-medium uppercase tracking-widest text-zinc-400";

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <PageHeader
        title="Настройки"
        description="Управление на системните параметри, сигурността и брандирането на клуба."
        breadcrumbs={[
          { label: "Начало", href: "/dashboard" },
          { label: "Настройки" },
        ]}
      >
        <Button
          onClick={handleSave}
          disabled={isSaving}
          className="rounded-xl font-medium uppercase tracking-widest text-[11px] h-12 px-8 bg-primary text-white hover:bg-primary/90 shadow-none transition-all"
        >
          {isSaving ? "Запазване..." : "Запази промените"}
          {!isSaving && <Save className="ml-3 h-4 w-4" strokeWidth={1.5} />}
        </Button>
      </PageHeader>

      <Tabs defaultValue="general" className="w-full">
        <div className="flex flex-col lg:flex-row gap-8">
          <div className="lg:w-72 space-y-3">
            <TabsList className="flex flex-col h-auto bg-transparent p-0 gap-3">
              <TabsTrigger
                value="general"
                className="w-full justify-start px-6 py-5 rounded-2xl data-[state=active]:bg-primary/5 transition-all border-none font-medium text-zinc-500 data-[state=active]:text-primary text-[13px] uppercase tracking-widest"
              >
                <Settings className="mr-4 h-5 w-5" strokeWidth={1.5} /> Общи
              </TabsTrigger>
              <TabsTrigger
                value="branding"
                className="w-full justify-start px-6 py-5 rounded-2xl data-[state=active]:bg-primary/5 transition-all border-none font-medium text-zinc-500 data-[state=active]:text-primary text-[13px] uppercase tracking-widest"
              >
                <Palette className="mr-4 h-5 w-5" strokeWidth={1.5} />{" "}
                Брандиране
              </TabsTrigger>
              <TabsTrigger
                value="security"
                className="w-full justify-start px-6 py-5 rounded-2xl data-[state=active]:bg-primary/5 transition-all border-none font-medium text-zinc-500 data-[state=active]:text-primary text-[13px] uppercase tracking-widest"
              >
                <Shield className="mr-4 h-5 w-5" strokeWidth={1.5} /> Сигурност
              </TabsTrigger>
              <TabsTrigger
                value="profile"
                className="w-full justify-start px-6 py-5 rounded-2xl data-[state=active]:bg-primary/5 transition-all border-none font-medium text-zinc-500 data-[state=active]:text-primary text-[13px] uppercase tracking-widest"
              >
                <User className="mr-4 h-5 w-5" strokeWidth={1.5} /> Личен Профил
              </TabsTrigger>

              <TabsTrigger
                value="recovery"
                className="w-full justify-start px-6 py-5 rounded-2xl data-[state=active]:bg-[#00f2fe]/10 transition-all border-none font-medium text-zinc-500 data-[state=active]:text-[#00f2fe] text-[13px] uppercase tracking-widest"
              >
                <Activity className="mr-4 h-5 w-5" strokeWidth={1.5} /> Зона
                Възстановяване
              </TabsTrigger>

              <TabsTrigger
                value="audit"
                className="w-full justify-start px-6 py-5 rounded-2xl data-[state=active]:bg-primary/5 transition-all border-none font-medium text-zinc-500 data-[state=active]:text-primary text-[13px] uppercase tracking-widest mt-8"
              >
                <Clock className="mr-4 h-5 w-5" strokeWidth={1.5} /> Системна
                история
              </TabsTrigger>
            </TabsList>
          </div>

          <div className="flex-1">
            <TabsContent
              value="general"
              className="m-0 focus-visible:outline-none"
            >
              <div className="grid grid-cols-1 gap-6">
                <BentoCard className="p-10 space-y-8 border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950">
                  <div className="flex items-center gap-4 mb-2">
                    <Building2
                      className="h-5 w-5 text-primary"
                      strokeWidth={1.5}
                    />
                    <h3 className="text-2xl font-light text-zinc-900 dark:text-white">
                      Информация за Клуба
                    </h3>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-3">
                      <Label className={labelClass}>Име на клуба</Label>
                      <Input
                        value={bkgData.name || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "bkgalabovo",
                            "name",
                            e.target.value
                          )
                        }
                        className={inputClass}
                      />
                    </div>
                    <div className="space-y-3">
                      <Label className={labelClass}>
                        <Mail className="inline h-3 w-3 mr-1" />
                        Официален Имейл
                      </Label>
                      <Input
                        value={bkgData.email || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "bkgalabovo",
                            "email",
                            e.target.value
                          )
                        }
                        className={inputClass}
                      />
                    </div>
                    <div className="space-y-3">
                      <Label className={labelClass}>
                        <Phone className="inline h-3 w-3 mr-1" />
                        Телефон за връзка
                      </Label>
                      <Input
                        value={bkgData.phone || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "bkgalabovo",
                            "phone",
                            e.target.value
                          )
                        }
                        className={inputClass}
                      />
                    </div>
                    <div className="space-y-3">
                      <Label className={labelClass}>
                        <Globe className="inline h-3 w-3 mr-1" />
                        Уебсайт
                      </Label>
                      <Input
                        value={bkgData.website || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "bkgalabovo",
                            "website",
                            e.target.value
                          )
                        }
                        placeholder="https://bkgalabovo.alle.bg/"
                        className={inputClass}
                      />
                    </div>
                    <div className="space-y-3 md:col-span-2">
                      <Label className={labelClass}>
                        <MapPin className="inline h-3 w-3 mr-1" />
                        Адрес
                      </Label>
                      <Input
                        value={bkgData.address || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "bkgalabovo",
                            "address",
                            e.target.value
                          )
                        }
                        placeholder="ул. Александър Стамболийски 41, 6280 Гълъбово, България"
                        className={inputClass}
                      />
                    </div>
                  </div>
                  <div className="pt-4 border-t border-zinc-50 dark:border-zinc-900">
                    <p className="text-[11px] font-medium uppercase tracking-widest text-zinc-400 mb-6">
                      Социални мрежи
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-3">
                        <Label className={labelClass}>
                          <InstagramIcon className="inline h-3 w-3 mr-1 text-pink-500" />
                          Instagram
                        </Label>
                        <Input
                          value={bkgData.instagram || ""}
                          onChange={(e) =>
                            handleInputChange(
                              "bkgalabovo",
                              "instagram",
                              e.target.value
                            )
                          }
                          placeholder="https://www.instagram.com/badminton.galabovo/"
                          className={inputClass}
                        />
                      </div>
                      <div className="space-y-3">
                        <Label className={labelClass}>
                          <YoutubeIcon className="inline h-3 w-3 mr-1 text-red-500" />
                          YouTube
                        </Label>
                        <Input
                          value={bkgData.youtube || ""}
                          onChange={(e) =>
                            handleInputChange(
                              "bkgalabovo",
                              "youtube",
                              e.target.value
                            )
                          }
                          placeholder="https://www.youtube.com/@BKGalabovo"
                          className={inputClass}
                        />
                      </div>
                      <div className="space-y-3">
                        <Label className={labelClass}>
                          <FacebookIcon className="inline h-3 w-3 mr-1 text-blue-500" />
                          Facebook Страница
                        </Label>
                        <Input
                          value={bkgData.facebook || ""}
                          onChange={(e) =>
                            handleInputChange(
                              "bkgalabovo",
                              "facebook",
                              e.target.value
                            )
                          }
                          placeholder="https://www.facebook.com/badmintongalabovo/"
                          className={inputClass}
                        />
                      </div>
                      <div className="space-y-3">
                        <Label className={labelClass}>
                          <Users className="inline h-3 w-3 mr-1 text-blue-400" />
                          Facebook Група (Родители и деца)
                        </Label>
                        <Input
                          value={bkgData.facebookGroup || ""}
                          onChange={(e) =>
                            handleInputChange(
                              "bkgalabovo",
                              "facebookGroup",
                              e.target.value
                            )
                          }
                          placeholder="https://www.facebook.com/groups/645571089477573/"
                          className={inputClass}
                        />
                      </div>
                    </div>
                  </div>
                </BentoCard>

                <BentoCard className="p-10 space-y-8 border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950">
                  <div className="flex items-center gap-4 mb-2">
                    <Activity
                      className="h-5 w-5 text-[#00f2fe]"
                      strokeWidth={1.5}
                    />
                    <h3 className="text-2xl font-light text-zinc-900 dark:text-white">
                      Информация за Зоната
                    </h3>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-3">
                      <Label className={labelClass}>Име на обекта</Label>
                      <Input
                        value={rzData.name || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "recoveryzone",
                            "name",
                            e.target.value
                          )
                        }
                        className={inputClassRz}
                      />
                    </div>
                    <div className="space-y-3">
                      <Label className={labelClass}>
                        <Mail className="inline h-3 w-3 mr-1" />
                        Официален Имейл
                      </Label>
                      <Input
                        value={rzData.email || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "recoveryzone",
                            "email",
                            e.target.value
                          )
                        }
                        className={inputClassRz}
                      />
                    </div>
                    <div className="space-y-3">
                      <Label className={labelClass}>
                        <Phone className="inline h-3 w-3 mr-1" />
                        Телефон за връзка
                      </Label>
                      <Input
                        value={rzData.phone || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "recoveryzone",
                            "phone",
                            e.target.value
                          )
                        }
                        className={inputClassRz}
                      />
                    </div>
                    <div className="space-y-3">
                      <Label className={labelClass}>
                        <Globe className="inline h-3 w-3 mr-1" />
                        Уебсайт
                      </Label>
                      <Input
                        value={rzData.website || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "recoveryzone",
                            "website",
                            e.target.value
                          )
                        }
                        className={inputClassRz}
                      />
                    </div>
                    <div className="space-y-3 md:col-span-2">
                      <Label className={labelClass}>
                        <MapPin className="inline h-3 w-3 mr-1" />
                        Адрес
                      </Label>
                      <Input
                        value={rzData.address || ""}
                        onChange={(e) =>
                          handleInputChange(
                            "recoveryzone",
                            "address",
                            e.target.value
                          )
                        }
                        className={inputClassRz}
                      />
                    </div>
                  </div>
                  <div className="pt-4 border-t border-zinc-50 dark:border-zinc-900">
                    <p className="text-[11px] font-medium uppercase tracking-widest text-zinc-400 mb-6">
                      Социални мрежи
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-3">
                        <Label className={labelClass}>
                          <InstagramIcon className="inline h-3 w-3 mr-1 text-pink-500" />
                          Instagram
                        </Label>
                        <Input
                          value={rzData.instagram || ""}
                          onChange={(e) =>
                            handleInputChange(
                              "recoveryzone",
                              "instagram",
                              e.target.value
                            )
                          }
                          placeholder="https://www.instagram.com/recoveryzonebyzm/"
                          className={inputClassRz}
                        />
                      </div>
                      <div className="space-y-3">
                        <Label className={labelClass}>
                          <FacebookIcon className="inline h-3 w-3 mr-1 text-blue-500" />
                          Facebook
                        </Label>
                        <Input
                          value={rzData.facebook || ""}
                          onChange={(e) =>
                            handleInputChange(
                              "recoveryzone",
                              "facebook",
                              e.target.value
                            )
                          }
                          placeholder="https://www.facebook.com/..."
                          className={inputClassRz}
                        />
                      </div>
                      <div className="space-y-3">
                        <Label className={labelClass}>
                          <YoutubeIcon className="inline h-3 w-3 mr-1 text-red-500" />
                          YouTube
                        </Label>
                        <Input
                          value={rzData.youtube || ""}
                          onChange={(e) =>
                            handleInputChange(
                              "recoveryzone",
                              "youtube",
                              e.target.value
                            )
                          }
                          placeholder="https://www.youtube.com/..."
                          className={inputClassRz}
                        />
                      </div>
                    </div>
                  </div>
                </BentoCard>

                {/* ── Localization + Status ── */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <BentoCard className="p-10 space-y-8 border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950">
                    <div className="flex items-center gap-4 mb-2">
                      <Globe
                        className="h-5 w-5 text-primary"
                        strokeWidth={1.5}
                      />
                      <h3 className="text-2xl font-light text-zinc-900 dark:text-white">
                        Локализация
                      </h3>
                    </div>
                    <div className="space-y-6">
                      <div className="space-y-3">
                        <Label className={labelClass}>Основна Валута</Label>
                        <div className="h-14 flex items-center px-5 rounded-xl bg-zinc-50 dark:bg-zinc-900 border border-zinc-100 dark:border-zinc-800 font-light text-zinc-700 dark:text-zinc-300">
                          EUR (€)
                        </div>
                      </div>
                      <div className="space-y-3">
                        <Label className={labelClass}>Часова Зона</Label>
                        <div className="h-14 flex items-center px-5 rounded-xl bg-zinc-50 dark:bg-zinc-900 border border-zinc-100 dark:border-zinc-800 font-light text-zinc-700 dark:text-zinc-300">
                          UTC+2 (Europe/Sofia)
                        </div>
                      </div>
                    </div>
                  </BentoCard>
                  <BentoCard className="p-10 space-y-6 border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950 flex flex-col justify-center items-center text-center">
                    <div className="h-20 w-20 bg-primary/5 text-primary rounded-3xl flex items-center justify-center mb-4 transition-all hover:scale-105">
                      <CheckCircle2 size={36} strokeWidth={1} />
                    </div>
                    <h4 className="font-light text-xl text-zinc-900 dark:text-white">
                      Системата е Оптимизирана
                    </h4>
                    <p className="text-sm text-zinc-400 max-w-[200px] font-light leading-relaxed">
                      Всички системни параметри са в нормални граници.
                    </p>
                  </BentoCard>
                </div>
              </div>
            </TabsContent>

            <TabsContent
              value="branding"
              className="m-0 focus-visible:outline-none"
            >
              <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                <BentoCard className="md:col-span-8 p-10 space-y-10 border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950">
                  <div className="flex items-center gap-4">
                    <Palette
                      className="h-5 w-5 text-primary"
                      strokeWidth={1.5}
                    />
                    <h3 className="text-2xl font-light text-zinc-900 dark:text-white">
                      Визуална Идентичност - Бадминтон Клуб
                    </h3>
                  </div>

                  <div className="space-y-8">
                    <div className="space-y-4">
                      <Label className="text-[11px] font-medium uppercase tracking-widest text-zinc-400">
                        Лого на Клуба
                      </Label>
                      <div className="flex items-center gap-8 p-8 rounded-2xl border border-dashed border-zinc-100 dark:border-zinc-800 bg-zinc-50/30 dark:bg-zinc-900/30">
                        <div className="h-28 w-28 bg-white rounded-3xl flex items-center justify-center shadow-none overflow-hidden border border-zinc-100">
                          <Image
                            src="/logo.png"
                            alt="BKG Logo"
                            width={80}
                            height={80}
                            className="object-contain"
                          />
                        </div>
                        <div className="space-y-3">
                          <Button
                            variant="outline"
                            className="rounded-xl border-zinc-200 dark:border-zinc-800 font-medium text-[11px] uppercase tracking-widest h-12 px-6 bg-white dark:bg-zinc-900"
                          >
                            <Camera
                              className="mr-3 h-4 w-4"
                              strokeWidth={1.5}
                            />{" "}
                            Промени Лого
                          </Button>
                          <p className="text-[11px] text-zinc-400 uppercase font-light tracking-wide">
                            Препоръчителен размер: 512x512px (PNG, SVG)
                          </p>
                        </div>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-8">
                      <div className="space-y-3">
