          <Button
            type="submit"
            disabled={loading || !name.trim()}
            className="w-full h-12 rounded-2xl bg-zinc-950 text-white hover:bg-zinc-900 transition-all text-xs uppercase tracking-widest font-bold"
          >
            {loading ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              "Създаване"
            )}
          </Button>
        </form>
      </DialogContent>
    </Dialog>
  );
};

