  const [selectedEventIds, setSelectedEventIds] = useState<string[]>([]);

  // Payment details
  const [price, setPrice] = useState(service.price.toString());
  const [paymentMethod, setPaymentMethod] = useState("В брой");
  const [isPaid, setIsPaid] = useState(true);
  const [note, setNote] = useState("");

  const [isProcessing, setIsProcessing] = useState(false);
  const [completedSaleId, setCompletedSaleId] = useState<string | null>(null);

  const { idToken } = useAuth();
  const { activeBranch } = useAppStore();

  // Reset state and load members on open
  useEffect(() => {
    if (isOpen) {
      const fetchMembers = async () => {
        setMembersLoading(true);
        try {
          const fetchedMembers = await getAllMembers();
          setMembers(fetchedMembers);
        } catch (err) {
          console.error("Error loading members:", err);
          toast.error("Грешка", { description: "Неуспешно зареждане на клубните членове." });
        } finally {
          setMembersLoading(false);
        }
      };
      fetchMembers();

      setStep(1);
      setPrice(service.price.toString());
      setSelectedMember(null);
      setIsGuestSale(false);
      setCompletedSaleId(null);
      setNote("");
      setSelectedMonthKeys([]);
      setSelectedEventIds([]);
      setMemberEvents([]);
      setPaymentMode(isSubscriptionService ? "subscription" : "individual");
      setSearchTerm("");
      setClientTypeTab("member");
      setShowNewGuestForm(false);
      setNewGuestFirstName("");
      setNewGuestLastName("");
      setNewGuestPhone("");
      setNewGuestEmail("");
      setIsSavingNewGuest(false);
    }
  }, [isOpen, service, isSubscriptionService]);

  const isFamilySubscription = useMemo(() => {
    return isSubscriptionService && service.name.toLowerCase().includes("семеен");
  }, [isSubscriptionService, service.name]);

  const familyMembers = useMemo(() => {
    if (!selectedMember || !isFamilySubscription) return [selectedMember];
    if (selectedMember.familyId) {
      return members.filter((m) => m.familyId === selectedMember.familyId);
    }
    return [selectedMember];
  }, [selectedMember, isFamilySubscription, members]);

  const targetMemberIds = useMemo(() => {
    return familyMembers.map((m) => m?.id).filter(Boolean) as string[];
  }, [familyMembers]);

  const clientDisplayName = useMemo(() => {
    if (isGuestSale) return "Външен клиент";
    if (isFamilySubscription && familyMembers.length > 0) {
      return familyMembers.map((m) => `${m?.firstName} ${m?.lastName}`).join(", ");
    }
    return `${selectedMember?.firstName} ${selectedMember?.lastName}`;
  }, [isGuestSale, isFamilySubscription, familyMembers, selectedMember]);

  // Load attendance
  useEffect(() => {
    if (selectedMember && !isGuestSale && step === 2) {
      const fetchAttendance = async () => {
        setAttendanceLoading(true);
        try {
          const fetchPromises = targetMemberIds.map((id) => getEventsByMemberId(id));
          const results = await Promise.all(fetchPromises);
          const events = results.flat();

          const attended = events.filter((e) => {
            const rec = e.attendees?.find((a: Attendee) => targetMemberIds.includes(a.memberId));
            return rec?.attended === true;
          });

          const uniqueEventsMap = new Map();
          attended.forEach((e) => uniqueEventsMap.set(e.id, e));
          setMemberEvents(Array.from(uniqueEventsMap.values()));
        } catch (err) {
          console.error("Error loading member attendance:", err);
          toast.error("Грешка", { description: "Неуспешно зареждане на присъствията." });
        } finally {
          setAttendanceLoading(false);
        }
      };
      fetchAttendance();
    }
  }, [selectedMember, isGuestSale, step, targetMemberIds]);

  const monthlyAttendance = useMemo((): MonthAttendance[] => {
    const groupedMap = new Map<string, MonthAttendance>();

    for (const event of memberEvents) {
      const d = new Date(event.startDate);
      const monthKey = format(d, "yyyy-MM");
      const monthLabel =
        format(d, "LLLL", { locale: bg }).charAt(0).toUpperCase() +
        format(d, "LLLL", { locale: bg }).slice(1) +
        " " +
        getYear(d);

      const targetAttendees = event.attendees?.filter((a: Attendee) =>
        targetMemberIds.includes(a.memberId)
      ) || [];

      if (!groupedMap.has(monthKey)) {
        groupedMap.set(monthKey, {
          monthKey,
          monthLabel,
          year: getYear(d),
          events: [],
          unpaidCount: 0,
          paidCount: 0,
          memberStats: {},
        });
      }

      const entry = groupedMap.get(monthKey)!;
      entry.events.push(event);

      for (const att of targetAttendees) {
        if (!entry.memberStats[att.memberId]) {
          const fm = familyMembers.find((m) => m?.id === att.memberId);
          entry.memberStats[att.memberId] = {
            memberId: att.memberId,
            firstName: fm?.firstName || "Неизвестен",
            paidCount: 0,
            unpaidCount: 0,
          };
        }

        if (att.paymentStatus === "paid") {
          entry.paidCount++;
          entry.memberStats[att.memberId].paidCount++;
        } else {
          entry.unpaidCount++;
          entry.memberStats[att.memberId].unpaidCount++;
        }
      }
    }

    return Array.from(groupedMap.values()).sort((a, b) => b.monthKey.localeCompare(a.monthKey));
  }, [memberEvents, targetMemberIds, familyMembers]);

  const unpaidEvents = useMemo(() => {
    return memberEvents
      .filter((e) => {
        return e.attendees?.some(
          (a: Attendee) =>
            targetMemberIds.includes(a.memberId) && (!a.paymentStatus || a.paymentStatus === "unpaid")
        );
      })
      .sort((a, b) => new Date(b.startDate).getTime() - new Date(a.startDate).getTime());
  }, [memberEvents, targetMemberIds]);

  const filteredMembers = members.filter((m) => {
    const fullName = `${m.firstName} ${m.lastName}`.toLowerCase();
    return fullName.includes(searchTerm.toLowerCase());
  });

  const unpaidMonths = useMemo(() => monthlyAttendance.filter((m) => m.unpaidCount > 0), [
    monthlyAttendance,
  ]);

  const allUnpaidMonthsSelected =
    unpaidMonths.length > 0 && unpaidMonths.every((m) => selectedMonthKeys.includes(m.monthKey));

  const totalAmount = useMemo(() => {
    const base = parseFloat(price) || 0;
    if (isGuestSale) return base;
    if (paymentMode === "subscription") {
      const months = selectedMonthKeys.length || 1;
      return base * months;
    }
    if (paymentMode === "individual") {
      const eventsCount = selectedEventIds.length || 1;
      return base * eventsCount;
    }
    return base;
  }, [price, isGuestSale, paymentMode, selectedMonthKeys, selectedEventIds]);

  const handleNextStep = () => {
    if (step === 1) {
      if (!selectedMember && !isGuestSale) {
        toast.error("Избор на клиент", { description: "Моля, изберете член от списъка или продажба на Външен клиент." });
        return;
      }
    }

    if (step === 2 && !isGuestSale) {
      if (paymentMode === "subscription" && selectedMonthKeys.length === 0) {
        toast.error("Избор на месец", { description: "Моля, изберете поне един месец за плащане." });
        return;
      }
      if (paymentMode === "individual" && selectedEventIds.length === 0) {
        toast.error("Избор на тренировки", { description: "Моля, изберете поне една процедура за плащане." });
        return;
      }
    }

    if (step === 3) {
      const priceVal = parseFloat(price);
      if (isNaN(priceVal) || priceVal < 0) {
        toast.error("Невалидна цена", { description: "Моля, въведете валидна цена." });
        return;
      }
    }

    setStep((prev) => prev + 1);
  };

  const handlePrevStep = () => {
    setStep((prev) => prev - 1);
  };

  const handleClose = () => {
    if (completedSaleId) {
      onSaleSuccess();
    } else {
      onClose();
    }
  };

  const toggleEventSelection = (eventId: string) => {
    setSelectedEventIds((prev) =>
      prev.includes(eventId) ? prev.filter((id) => id !== eventId) : [...prev, eventId]
    );
  };

  const toggleMonthSelection = (monthKey: string) => {
    setSelectedMonthKeys((prev) =>
      prev.includes(monthKey) ? prev.filter((k) => k !== monthKey) : [...prev, monthKey]
    );
  };

  const getPaidEventIds = () => {
    if (isGuestSale || paymentMode !== "subscription") return [];

    return monthlyAttendance
      .filter((m) => selectedMonthKeys.includes(m.monthKey))
      .flatMap((m) =>
        m.events
          .filter((e) => {
            return e.attendees?.some(
              (a: Attendee) =>
                targetMemberIds.includes(a.memberId) && (!a.paymentStatus || a.paymentStatus === "unpaid")
            );
          })
          .map((e) => e.id)
      );
  };

  const handleExecuteSale = async () => {
    if (!idToken) return;
    setIsProcessing(true);
    setStep(5);

    const customPrice = parseFloat(price);
    const qty = isGuestSale ? 1 : paymentMode === "subscription" ? selectedMonthKeys.length || 1 : selectedEventIds.length || 1;

    try {
      const clientName = isGuestSale
        ? "Външен клиент"
        : familyMembers.map((m) => `${m!.firstName} ${m!.lastName}`).join(", ");

      const selectedMonthLabelsArr = monthlyAttendance
        .filter((m) => selectedMonthKeys.includes(m.monthKey))
        .sort((a, b) => a.monthKey.localeCompare(b.monthKey))
        .map((m) => m.monthLabel);

      const targetEventDates = isGuestSale || paymentMode !== "individual" ? null : selectedEventIds
        .map((id) => {
          const ev = memberEvents.find((e) => e.id === id);
          return ev ? new Date(ev.startDate).toLocaleDateString("bg-BG") : null;
        })
        .filter(Boolean);

      const paidEventIdsForSale = isGuestSale ? [] : paymentMode === "individual" ? selectedEventIds : getPaidEventIds();

      const saleData = {
        siteId: activeBranch || "bkgalabovo",
        memberId: isGuestSale ? "GUEST_EXTERNAL" : selectedMember!.id,
        clientName: clientName,
        saleDate: new Date().toISOString(),
        items: [
          {
            productId: service.id,
            name: service.name,
            quantity: qty,
            price: customPrice,
          },
        ],
        status: "completed",
        isPaid: isPaid,
        totalAmount: totalAmount,
        currency: "EUR",
        paymentMethod: paymentMethod,
        note: note || "",
        type: "recovery_service", // Important: type is recovery_service
        paymentMode: isGuestSale ? null : paymentMode,
        targetMonths: isGuestSale ? null : selectedMonthKeys,
        targetMonthLabels: isGuestSale ? null : selectedMonthLabelsArr,
        targetEventDates: targetEventDates,
        paidEventIds: paidEventIdsForSale,
        memberIdForAttendance: isGuestSale ? null : selectedMember?.id,
        memberIdsForAttendance: isGuestSale ? null : targetMemberIds,
      };

      const result = await executeTrainingSaleAction(idToken, saleData, service.name, clientName);

      if (result.success && result.saleId) {
        setCompletedSaleId(result.saleId);
        setStep(6);
        if (!isGuestSale && selectedMember) {
          mutate(selectedMember.id);
          mutate(`events_${selectedMember.id}`);
        }
        toast.success("Готово!", { description: "Продажбата бе регистрирана успешно." });
      } else {
        setStep(4);
        toast.error("Грешка", { description: result.error || "Грешка при продажба" });
      }
    } catch (error: any) {
      setStep(4);
      toast.error("Грешка при продажба", { description: error.message });
    } finally {
      setIsProcessing(false);
    }
  };

  const selectedMonthLabels = monthlyAttendance
    .filter((m) => selectedMonthKeys.includes(m.monthKey))
    .sort((a, b) => a.monthKey.localeCompare(b.monthKey))
    .map((m) => m.monthLabel);

  const steps = isGuestSale
    ? ["Клиент", "Плащане", "Преглед"]
    : ["Клиент", "Присъствия", "Плащане", "Преглед"];
  const totalSteps = steps.length;
  const displayStep = Math.min(step, totalSteps);

  const contextValue: RecoveryWizardContextType = {
    step,
    setStep,
    totalSteps,
    displayStep,
    isProcessing,
    completedSaleId,
    service,
    handleClose,
    handlePrevStep,
    handleNextStep,
    handleExecuteSale,
    members,
    setMembers,
    membersLoading,
    searchTerm,
    setSearchTerm,
    selectedMember,
    setSelectedMember,
    isGuestSale,
    setIsGuestSale,
    clientTypeTab,
    setClientTypeTab,
    showNewGuestForm,
    setShowNewGuestForm,
    newGuestFirstName,
    setNewGuestFirstName,
    newGuestLastName,
    setNewGuestLastName,
    newGuestPhone,
    setNewGuestPhone,
    newGuestEmail,
    setNewGuestEmail,
    isSavingNewGuest,
    setIsSavingNewGuest,
    filteredMembers,
    clientDisplayName,
    attendanceLoading,
    memberEvents,
    paymentMode,
    setPaymentMode,
    monthlyAttendance,
    unpaidMonths,
    selectedMonthKeys,
    setSelectedMonthKeys,
    allUnpaidMonthsSelected,
    toggleMonthSelection,
    unpaidEvents,
    selectedEventIds,
    setSelectedEventIds,
    toggleEventSelection,
    selectedMonthLabels,
    price,
    setPrice,
    paymentMethod,
    setPaymentMethod,
    isPaid,
    setIsPaid,
    note,
    setNote,
    totalAmount,
  };

  return <RecoveryWizardContext.Provider value={contextValue}>{children}</RecoveryWizardContext.Provider>;
};

export const useRecoveryWizard = () => {
  const context = useContext(RecoveryWizardContext);
  if (!context) {
    throw new Error("useRecoveryWizard must be used within a RecoveryWizardProvider");
  }
  return context;
};

"use client";

import { useRecoveryWizard } from "./RecoveryWizardContext";
import { User, Search, Check, PlusCircle, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { createMemberAction } from "@/lib/actions/members";
import { useAuth } from "@/context/auth-context";
import { useAppStore } from "@/store/use-app-store";
import { Member } from "@/types";

export const RecoveryWizardStep1 = () => {
  const {
    showNewGuestForm,
    setShowNewGuestForm,
    clientTypeTab,
    setClientTypeTab,
    setSelectedMember,
    setIsGuestSale,
    newGuestFirstName,
    setNewGuestFirstName,
    newGuestLastName,
    setNewGuestLastName,
    newGuestPhone,
    setNewGuestPhone,
    newGuestEmail,
    setNewGuestEmail,
    isSavingNewGuest,
    setIsSavingNewGuest,
    searchTerm,
    setSearchTerm,
    membersLoading,
    filteredMembers,
    selectedMember,
    setMembers,
    setStep,
  } = useRecoveryWizard();

  const { idToken } = useAuth();
  const { activeBranch } = useAppStore();

  const handleRegisterGuest = async () => {
    if (!newGuestFirstName || !newGuestLastName || !newGuestPhone) {
      toast.error("Непълни данни", {
        description: "Моля, попълнете Име, Фамилия и Телефон на госта.",
      });
      return;
    }
    setIsSavingNewGuest(true);
    try {
      const result = await createMemberAction(idToken!, {
        firstName: newGuestFirstName,
        lastName: newGuestLastName,
        phone: newGuestPhone,
        email: newGuestEmail || "",
        isGuest: true,
        memberType: "guest",
        status: "active",
        siteId: activeBranch || "bkgalabovo",
      });

      if (result.success && result.data) {
        const newGuestObj: Member = {
          id: result.data.id,
          firstName: newGuestFirstName,
          lastName: newGuestLastName,
          name: `${newGuestFirstName} ${newGuestLastName}`,
          phone: newGuestPhone,
          email: newGuestEmail || "",
          isGuest: true,
          memberType: "guest",
          status: "active",
          siteId: activeBranch || "bkgalabovo",
          registrationDate: new Date().toISOString(),
        } as any;

        setMembers((prev) => [newGuestObj, ...prev]);
        setSelectedMember(newGuestObj);
        setIsGuestSale(true);

        toast.success("Успех!", {
          description: "Външният клиент беше регистриран и избран успешно.",
        });

        setShowNewGuestForm(false);
        setNewGuestFirstName("");
        setNewGuestLastName("");
        setNewGuestPhone("");
        setNewGuestEmail("");
        setStep(3); // Guests bypass Step 2 (attendance selection)
      } else {
        toast.error("Грешка при регистрация", {
          description: result.message,
        });
      }
    } catch (err) {
      console.error("Error creating quick guest:", err);
      toast.error("Системна грешка при регистрация.");
    } finally {
      setIsSavingNewGuest(false);
    }
  };

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between pb-2 border-b border-zinc-100 dark:border-zinc-900">
        <div className="flex items-center gap-2">
          <User className="h-4 w-4 text-emerald-500" strokeWidth={1.5} />
          <h3 className="text-sm font-semibold text-zinc-950 dark:text-zinc-50">
            Избор на клиент
          </h3>
        </div>
      </div>

      {showNewGuestForm ? (
        <div className="space-y-4 p-5 border border-amber-200 dark:border-amber-900/35 bg-amber-50/20 dark:bg-amber-950/5 rounded-2xl animate-in fade-in duration-300">
          <h4 className="text-xs font-bold uppercase tracking-wider text-amber-800 dark:text-amber-400">
            Регистрация на Нов Външен клиент (Гост)
          </h4>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label className="text-[10px] font-bold uppercase text-zinc-500">Име *</Label>
              <Input
                placeholder="Име"
                value={newGuestFirstName}
                onChange={(e) => setNewGuestFirstName(e.target.value)}
                className="h-10 rounded-xl border-zinc-200 text-xs"
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-[10px] font-bold uppercase text-zinc-500">Фамилия *</Label>
              <Input
                placeholder="Фамилия"
                value={newGuestLastName}
                onChange={(e) => setNewGuestLastName(e.target.value)}
                className="h-10 rounded-xl border-zinc-200 text-xs"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label className="text-[10px] font-bold uppercase text-zinc-500">Телефон *</Label>
              <Input
                placeholder="Телефон"
                value={newGuestPhone}
                onChange={(e) => setNewGuestPhone(e.target.value)}
                className="h-10 rounded-xl border-zinc-200 text-xs"
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-[10px] font-bold uppercase text-zinc-500">Имейл</Label>
              <Input
                placeholder="Имейл (по избор)"
                value={newGuestEmail}
                onChange={(e) => setNewGuestEmail(e.target.value)}
                className="h-10 rounded-xl border-zinc-200 text-xs"
              />
            </div>
          </div>

          <div className="flex gap-2 justify-end pt-2">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              disabled={isSavingNewGuest}
              onClick={() => setShowNewGuestForm(false)}
              className="rounded-xl text-xs"
            >
              Отказ
            </Button>
            <Button
              type="button"
              size="sm"
              disabled={isSavingNewGuest}
              onClick={handleRegisterGuest}
              className="rounded-xl text-xs bg-amber-500 hover:bg-amber-600 text-white animate-in"
            >
              {isSavingNewGuest && <Loader2 className="h-3 w-3 animate-spin mr-1" />}
              Регистрирай и избери
            </Button>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex bg-zinc-100 dark:bg-zinc-900 rounded-xl p-1 gap-1">
            <button
              type="button"
              onClick={() => {
                setClientTypeTab("member");
                setSelectedMember(null);
                setIsGuestSale(false);
              }}
              className={cn(
                "flex-1 py-2 text-[10px] font-semibold uppercase tracking-widest rounded-lg transition-all",
                clientTypeTab === "member"
                  ? "bg-white dark:bg-zinc-800 text-zinc-900 dark:text-white shadow-sm font-bold"
                  : "text-zinc-500 hover:text-zinc-700"
              )}
            >
              Клубни членове
            </button>
            <button
              type="button"
              onClick={() => {
                setClientTypeTab("guest");
                setSelectedMember(null);
                setIsGuestSale(true);
              }}
              className={cn(
                "flex-1 py-2 text-[10px] font-semibold uppercase tracking-widest rounded-lg transition-all",
                clientTypeTab === "guest"
                  ? "bg-white dark:bg-zinc-800 text-zinc-900 dark:text-white shadow-sm font-bold"
                  : "text-zinc-500 hover:text-zinc-700"
              )}
            >
              Външни клиенти (Гости)
            </button>
          </div>

          <div className="flex gap-2">
            <div className="relative flex-1 group">
              <Search
                className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400 group-focus-within:text-emerald-500 transition-colors"
                strokeWidth={1.5}
              />
              <Input
                placeholder={
                  clientTypeTab === "guest"
                    ? "Търсене на външен гост..."
                    : "Търсене на член по име..."
                }
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-11 rounded-xl h-11 border-zinc-200 focus-visible:ring-emerald-500 focus-visible:border-emerald-500"
              />
            </div>
            {clientTypeTab === "guest" && (
              <Button
                type="button"
                onClick={() => setShowNewGuestForm(true)}
                className="rounded-xl h-11 bg-amber-500 hover:bg-amber-600 text-white font-semibold text-[10px] uppercase tracking-wider shrink-0 px-4 shadow-none"
              >
                <PlusCircle className="mr-1.5 h-4 w-4" /> Нов Гост
              </Button>
            )}
          </div>

          {membersLoading ? (
            <div className="py-16 flex flex-col items-center justify-center space-y-4">
              <Loader2 className="h-8 w-8 animate-spin text-emerald-500 opacity-30" />
              <p className="text-zinc-400 text-xs font-light">Зареждане на списъка...</p>
            </div>
          ) : (
            <div className="border border-zinc-100 dark:border-zinc-900 rounded-2xl max-h-[240px] overflow-y-auto divide-y divide-zinc-50 dark:divide-zinc-900 custom-scrollbar">
              {filteredMembers.length > 0 ? (
                filteredMembers.map((member) => {
                  const isSelected = selectedMember?.id === member.id;
                  let buttonClass = "w-full text-left px-5 py-3.5 flex justify-between items-center transition-colors text-sm font-light ";
                  if (!isSelected) {
                    buttonClass += "hover:bg-zinc-50 dark:hover:bg-zinc-900/50 text-zinc-800 dark:text-zinc-200";
                  } else if (clientTypeTab === "guest") {
                    buttonClass += "bg-amber-500/10 text-amber-950 dark:bg-amber-950/20 dark:text-amber-300";
                  } else {
                    buttonClass += "bg-emerald-50 text-emerald-950 dark:bg-emerald-950/20 dark:text-emerald-300";
                  }

                  let avatarClass = "h-7 w-7 rounded-lg flex items-center justify-center text-[10px] font-semibold shrink-0 ";
                  if (!isSelected) {
                    avatarClass += "bg-zinc-100 dark:bg-zinc-800 text-zinc-500";
                  } else if (clientTypeTab === "guest") {
                    avatarClass += "bg-amber-500 text-white";
                  } else {
                    avatarClass += "bg-emerald-500 text-white";
                  }

                  return (
                    <button
                      key={member.id}
                      type="button"
                      onClick={() => {
                        setSelectedMember(member);
                        setIsGuestSale(member.isGuest || false);
                      }}
                      className={buttonClass}
                    >
                      <div className="flex items-center gap-3">
                        <div className={avatarClass}>
                          {member.firstName[0]}
                          {member.lastName[0]}
                        </div>
                        <div className="flex flex-col">
                          <span className="font-medium text-zinc-900 dark:text-zinc-50">
                            {member.firstName} {member.lastName}
                          </span>
                          <span className="text-[10px] text-zinc-400 font-light mt-0.5">
                            {member.phone || member.email || "Няма контакти"}
                          </span>
                        </div>
                      </div>
                      {isSelected && (
                        <Check
                          className={cn(
                            "h-4 w-4 shrink-0",
                            clientTypeTab === "guest" ? "text-amber-500" : "text-emerald-500"
                          )}
                        />
                      )}
                    </button>
                  );
                })
              ) : (
                <div className="p-8 text-center text-zinc-400 text-xs font-light">
                  {clientTypeTab === "guest"
                    ? "Няма регистрирани външни гости. Създайте нов гост от бутона вдясно!"
                    : "Няма намерени членове по този критерий."}
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

