                  {clientTypeTab === "guest"
                    ? "Няма регистрирани външни гости. Създайте нов гост от бутона вдясно!"
                    : "Няма намерени членове по този критерий."}
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

