                  let avatarBgClass = "bg-zinc-100 dark:bg-zinc-800 text-zinc-500";

                  if (isSelected) {
                    if (clientTypeTab === "guest") {
                      btnBgClass = "bg-amber-500/10 text-amber-950 dark:bg-amber-950/20 dark:text-amber-300";
