                </Link>
              </SidebarMenuButton>
            </SidebarMenuItem>

            {!isRecoveryZone && (
              <>
                <li className="px-4 py-2 mt-4 text-[10px] font-semibold text-zinc-500 dark:text-zinc-400 uppercase tracking-wider">
                  Тренировъчен процес
