                  <p className="text-[10px] font-light text-zinc-400 uppercase tracking-widest truncate mt-1">
                    {familyMember.status === "active"
                      ? "Активен"
                      : "Неактивен"}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

