"use client";

import { format } from "date-fns";
import { bg } from "date-fns/locale";
import { TableCell, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  User,
  Clock,
  MapPin,
  Eye,
  Activity,
  CheckCircle2,
  FileText,
  Pencil,
  Trash2,
} from "lucide-react";
import { ReservationDialog } from "./reservation-dialog";
import { DonationReceiptDialog } from "./donation-receipt-dialog";

export const getReservationTitle = (res: any) => {
  const c1Name = res.clientName;
  const c1Zone = res.selectedZone ? ` (${res.selectedZone})` : "";
  const c1Str = `${c1Name}${c1Zone}`;

  if (res.client2Name || res.client2Zone) {
    const c2Name = res.client2Name || "Клиент 2";
    const c2Zone = res.client2Zone ? ` (${res.client2Zone})` : "";
    return `${c1Str} & ${c2Name}${c2Zone}`;
  }
  return c1Str;
};

export const getStatusLabel = (status: string) => {
  switch (status) {
    case "paid":
      return "Платена";
    case "unpaid":
      return "Неплатена";
    case "cancelled":
      return "Отказана";
    case "confirmed":
      return "Потвърдена";
    case "scheduled":
      return "Планирана";
    case "completed":
      return "Завършена";
    case "pending":
      return "Изчакваща";
    default:
      return status;
  }
};

export const getStatusStyles = (status: string) => {
  switch (status) {
    case "paid":
    case "completed":
    case "confirmed":
      return "bg-emerald-500/10 text-emerald-600 hover:bg-emerald-500/20";
    case "cancelled":
      return "bg-red-500/10 text-red-600";
    case "pending":
    case "unpaid":
      return "bg-amber-500/10 text-amber-600";
    default:
      return "bg-zinc-500/10 text-zinc-600";
  }
};

interface ReservationHistoryTableRowProps {
