// This component is designed specifically for printing.
import React from "react";
import { ScheduleEvent, Member, ScheduleEventType, Attendee } from "@/types";
import { formatDateTimeDisplay } from "@/lib/date-utils";

// Removed local formatDate as we use the centralized one.

interface PrintableEventProps {
  event: ScheduleEvent;
  members: Member[];
  eventTypeTranslations: Record<ScheduleEventType, string>;
}

export const PrintableEvent: React.FC<PrintableEventProps> = ({
  event,
  members,
  eventTypeTranslations,
}) => {
  if (!event) return null;

  const attendeeNames = (event.attendees || [])
    .map((attendee: Attendee) => {
      const member = members.find((m) => m.id === attendee.memberId);
      return member ? `${member.firstName} ${member.lastName}` : null;
    })
    .filter(Boolean)
    .join(", ");

  const translatedEventType = event.type
    ? eventTypeTranslations[event.type]
    : "Няма посочен";

  return (
    <div className="p-4 font-sans text-sm">
      <h1 className="text-xl font-bold mb-4 border-b pb-2">
        Детайли за събитието
      </h1>
      <div className="grid grid-cols-3 gap-x-4 gap-y-2">
        <p className="font-semibold col-span-1">Заглавие:</p>
        <p className="col-span-2">{event.title}</p>

        <p className="font-semibold col-span-1">Начало:</p>
        <p className="col-span-2">{formatDateTimeDisplay(event.startDate)}</p>

        <p className="font-semibold col-span-1">Край:</p>
        <p className="col-span-2">{formatDateTimeDisplay(event.endDate)}</p>

        <p className="font-semibold col-span-1">Място:</p>
        <p className="col-span-2">{event.location || "Няма посочено"}</p>

        <p className="font-semibold col-span-1">Тип:</p>
        <p className="col-span-2">{translatedEventType}</p>

        {attendeeNames && (
          <>
            <p className="font-semibold col-span-1 mt-2">Присъстващи:</p>
            <p className="col-span-2 mt-2">{attendeeNames}</p>
          </>
        )}
      </div>
      <p
        className="text-xs text-gray-500 mt-6 pt-2 border-t"
        suppressHydrationWarning
      >
        Генерирано на: {formatDateTimeDisplay(new Date())}
      </p>
    </div>
  );
};

"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { Button } from "@/components/ui/button";
import { Form } from "@/components/ui/form";
import { Loader2, ArrowRight, ArrowLeft } from "lucide-react";
import { format } from "date-fns";
import { cn } from "@/lib/utils";
import { useState, useCallback, useEffect } from "react";

import { MonthlyScheduleStep1 } from "./MonthlyScheduleStep1";
import { MonthlyScheduleStep2 } from "./MonthlyScheduleStep2";
import { MonthlyScheduleStep3 } from "./MonthlyScheduleStep3";

export const daysOfWeek = [
  { id: "mon", label: "Пн", value: 1 },
  { id: "tue", label: "Вт", value: 2 },
  { id: "wed", label: "Ср", value: 3 },
  { id: "thu", label: "Чт", value: 4 },
  { id: "fri", label: "Пт", value: 5 },
  { id: "sat", label: "Сб", value: 6 },
  { id: "sun", label: "Нд", value: 0 },
];

export const monthlyScheduleSchema = z
  .object({
    title: z.string().min(1, "Моля, въведете заглавие."),
    type: z.enum(["training", "competition", "camp", "event", "other"]),
    month: z.string().min(1, "Моля, изберете месец."),
    days: z.array(z.number()).min(1, "Моля, изберете поне един ден."),
    startTime: z.string().min(1, "Моля, въведете начален час."),
    endTime: z.string().min(1, "Моля, въведете краен час."),
    location: z.string().min(1, "Моля, въведете локация."),
  })
  .refine((data) => data.startTime < data.endTime, {
    message: "Крайният час трябва да е след началния.",
    path: ["endTime"],
  });

export type MonthlyScheduleFormData = z.infer<typeof monthlyScheduleSchema>;

interface MonthlyScheduleFormProps {
  onSave: (data: MonthlyScheduleFormData) => void;
  isSaving?: boolean;
}

export default function MonthlyScheduleForm({
  onSave,
  isSaving,
}: MonthlyScheduleFormProps) {
  const [step, setStep] = useState(1);

  const form = useForm<MonthlyScheduleFormData>({
    resolver: zodResolver(monthlyScheduleSchema),
    defaultValues: {
      title: "Тренировка",
      type: "training",
      month: format(new Date(), "yyyy-MM"),
      days: [],
      startTime: "17:00",
      endTime: "18:30",
      location: 'Спортна зала "Енергетик" град Гълъбово',
    },
  });

  const currentValues = form.getValues();
  const [canSubmit, setCanSubmit] = useState(false);

  useEffect(() => {
    if (step === 3) {
      const timer = setTimeout(() => setCanSubmit(true), 600);
      return () => clearTimeout(timer);
    } else {
      setCanSubmit(false);
    }
  }, [step]);

  const handleNextStep = useCallback(async () => {
    let isValid = false;
    if (step === 1) {
      isValid = await form.trigger(["title", "type", "location"]);
    } else if (step === 2) {
      isValid = await form.trigger(["month", "days", "startTime", "endTime"]);
    }
    if (isValid) {
      setStep((prev) => prev + 1);
    }
  }, [step, form]);

  const handlePrevStep = useCallback(() => {
    setStep((prev) => prev - 1);
  }, []);

  const handleInputKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (step < 3) {
          handleNextStep();
        } else {
          form.handleSubmit(onSave)();
        }
      }
    },
    [step, handleNextStep, form, onSave]
  );

  return (
    <div className="flex flex-col h-full">
      <div className="mb-6 space-y-2">
        <div className="flex items-center justify-between text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400">
          <span>
            {step === 1
              ? "Стъпка 1: Основна информация"
              : step === 2
                ? "Стъпка 2: Време и Повторяемост"
                : "Стъпка 3: Финализиране"}
          </span>
          <span>Стъпка {step} от 3</span>
        </div>
        <div className="flex gap-2">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className={cn(
                "h-1.5 flex-1 rounded-full transition-all duration-500 ease-out",
                i === step
                  ? "bg-zinc-950 dark:bg-white"
                  : i < step
                    ? "bg-zinc-950/30 dark:bg-white/30"
                    : "bg-zinc-100 dark:bg-zinc-800"
              )}
            />
          ))}
        </div>
      </div>

      <Form {...form}>
        <form
          id="monthly-schedule-form"
          onSubmit={(e) => {
            e.preventDefault();
            if (step < 3) {
              handleNextStep();
            } else {
              form.handleSubmit(onSave)();
            }
          }}
          className="space-y-8 flex-1"
        >
          <MonthlyScheduleStep1 
            form={form} 
            isActive={step === 1} 
            onKeyDown={handleInputKeyDown} 
          />

          <MonthlyScheduleStep2 
            form={form} 
            isActive={step === 2} 
            onKeyDown={handleInputKeyDown}
            daysOfWeek={daysOfWeek}
          />

          <MonthlyScheduleStep3 
            isActive={step === 3} 
            currentValues={currentValues}
            daysOfWeek={daysOfWeek}
          />

          {/* NAVIGATION BUTTONS */}
          <div className="flex items-center justify-between gap-4 pt-6 border-t border-zinc-100 dark:border-zinc-900 mt-8">
            {step > 1 && (
              <Button
                type="button"
                variant="ghost"
                onClick={handlePrevStep}
                className="h-11 rounded-xl text-xs font-medium uppercase tracking-wider text-zinc-500 hover:border-zinc-50 hover:bg-zinc-50 gap-2 px-4"
              >
                <ArrowLeft className="h-3 w-3" /> Назад
              </Button>
            )}
            {step < 3 ? (
              <Button
                type="button"
                onClick={handleNextStep}
                className={cn(
                  "h-11 rounded-xl text-xs font-medium uppercase tracking-wider gap-2 px-5 ml-auto",
                  "bg-zinc-950 text-white hover:border-zinc-900 hover:bg-zinc-900 shadow-md shadow-zinc-950/10"
                )}
              >
                Напред <ArrowRight className="h-3 w-3" />
              </Button>
            ) : (
              <Button
                type="submit"
                disabled={isSaving || !canSubmit}
                className={cn(
                  "h-11 rounded-xl text-xs font-medium uppercase tracking-wider gap-2 px-6 ml-auto transition-all",
                  canSubmit
                    ? "bg-zinc-950 text-white hover:border-zinc-900 hover:bg-zinc-900 shadow-lg shadow-zinc-950/20"
                    : "bg-zinc-300 text-zinc-500 cursor-not-allowed opacity-70"
                )}
              >
                {isSaving ? (
                  <>
                    <Loader2 className="h-3 w-3 animate-spin" /> Запазване...
                  </>
                ) : (
                  "Потвърди и създай"
                )}
              </Button>
            )}
          </div>
        </form>
      </Form>
    </div>
  );
}

