                          type="checkbox"
                          checked={isChecked}
                          onChange={(e) => {
                            const current = field.value || [];
                            const next = e.target.checked
                              ? [...current, item.id]
                              : current.filter((v) => v !== item.id);
                            field.onChange(next);
