"use client";
import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "@/lib/utils";
import { Menu, X } from "lucide-react";
import { useAppStore } from "@/store/use-app-store";

const SidebarContext = React.createContext<{
  state: "expanded" | "collapsed";
  open: boolean;
  setOpen: (value: boolean | ((prev: boolean) => boolean)) => void;
  isMobile: boolean;
} | null>(null);

export function useSidebar() {
  const context = React.useContext(SidebarContext);
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider");
  }
  return context;
}

export const SidebarProvider = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    defaultOpen?: boolean;
    open?: boolean;
    onOpenChange?: (open: boolean) => void;
  }
>(
  (
    {
      defaultOpen: _defaultOpen = true,
      open: openProp,
      onOpenChange,
      className,
      children,
      ...props
    },
    ref
  ) => {
    const isMobile = useIsMobile();
    const { isSidebarOpen, setSidebarOpen } = useAppStore();

    // Support external control via props, but fallback to global store
    const open = openProp ?? isSidebarOpen;

    const setOpen = React.useCallback(
      (value: boolean | ((prev: boolean) => boolean)) => {
        const nextValue = typeof value === "function" ? value(open) : value;
        console.log("Sidebar: setting open to", nextValue);
        if (onOpenChange) {
          onOpenChange(nextValue);
        }
        setSidebarOpen(nextValue);
      },
      [onOpenChange, open, setSidebarOpen]
    );

    const state = (open ? "expanded" : "collapsed") as "expanded" | "collapsed";

    const contextValue = React.useMemo(
      () => ({ state, open, setOpen, isMobile }),
      [state, open, setOpen, isMobile]
    );

    return (
      <SidebarContext.Provider value={contextValue}>
        <div
          className={cn(
            "group/sidebar-wrapper flex min-h-svh w-full has-data-[variant=inset]:bg-sidebar",
            className
          )}
          ref={ref}
          {...props}
        >
          {children}
        </div>
      </SidebarContext.Provider>
    );
  }
);
SidebarProvider.displayName = "SidebarProvider";

export const Sidebar = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    side?: "left" | "right";
    variant?: "sidebar" | "floating" | "inset";
    collapsible?: "offcanvas" | "icon" | "none";
  }
>(
  (
    {
      side = "left",
      variant = "sidebar",
      collapsible = "offcanvas",
      className,
      children,
      ...props
    },
    ref
  ) => {
    const { isMobile, open, setOpen } = useSidebar();

    if (isMobile) {
      return (
        <>
          {open && (
            <div
              className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm animate-in fade-in duration-300"
              onClick={() => setOpen(false)}
            />
          )}
          <div
            ref={ref}
            role="dialog"
            aria-modal="true"
            className={cn(
              "fixed inset-y-0 left-0 z-999 w-[280px] bg-white dark:bg-zinc-950 flex flex-col transition-all duration-300 ease-in-out border-r border-zinc-100 dark:border-zinc-900 shadow-2xl pointer-events-auto overflow-y-auto",
              open
                ? "translate-x-0 opacity-100 visible"
                : "-translate-x-full opacity-0 invisible",
              className
            )}
            {...props}
          >
            {children}
          </div>
        </>
      );
    }

    return (
      <div
        ref={ref}
        className={cn(
          "group peer hidden md:block text-sidebar-foreground border-r border-sidebar-border",
          className
        )}
        data-state={open ? "expanded" : "collapsed"}
        data-collapsible={collapsible}
        data-variant={variant}
        data-side={side}
        {...props}
      >
        {children}
      </div>
    );
  }
);
Sidebar.displayName = "Sidebar";

