    const targetMemberIds = [memberId];

    if (!familyQuerySnap.empty) {
      const familyDoc = familyQuerySnap.docs[0];
      family = serializeFirestoreData({
        ...familyDoc.data(),
        id: familyDoc.id,
      }) as Family;

      const otherMemberIds = family.memberIds.filter((id) => id !== memberId);
      if (otherMemberIds.length > 0) {
        targetMemberIds.push(...otherMemberIds);

        // Fetch other family members concurrently
        const otherMembersSnaps = await Promise.all(
          otherMemberIds.map((id) =>
            adminDb.collection("members").doc(id).get()
          )
        );
        familyMembers = otherMembersSnaps
          .filter((snap) => snap.exists)
          .map((snap) => snapToData<Member>(snap));
      }
    }

    // Fetch sales for all family members (or single member if no family) concurrently
    const salesSnaps = await Promise.all(
      targetMemberIds.map((id) =>
        adminDb.collection("sales").where("memberId", "==", id).get()
      )
    );

    // Also fetch sales where memberIdsForAttendance contains the memberId
    const salesAttendanceSnaps = await Promise.all(
      targetMemberIds.map((id) =>
        adminDb
          .collection("sales")
          .where("memberIdsForAttendance", "array-contains", id)
          .get()
      )
    );

    // Merge and deduplicate sales
    const salesMap = new Map<string, Sale>();

    salesSnaps.forEach((querySnap) => {
      querySnap.docs.forEach((doc) => {
        const sale = snapToData<Sale>(doc);
        salesMap.set(sale.id, sale);
      });
    });

    salesAttendanceSnaps.forEach((querySnap) => {
      querySnap.docs.forEach((doc) => {
        const sale = snapToData<Sale>(doc);
        salesMap.set(sale.id, sale);
      });
    });

    const sales = Array.from(salesMap.values()).sort(
      (a, b) => new Date(b.saleDate).getTime() - new Date(a.saleDate).getTime()
    );

    return {
      success: true,
      data: {
        member: memberData,
        family,
        familyMembers,
        attendances,
        sales,
      },
    };
  } catch (error: any) {
    console.error("getMemberProfileDataServerAction Error:", error);
    return {
      success: false,
      message: error.message || "Р“СЂРµС€РєР° РїСЂРё РёР·РІР»РёС‡Р°РЅРµ РЅР° РїСЂРѕС„РёР»Р°.",
    };
  }
}

﻿import * as admin from "firebase-admin";

let adminDb: admin.firestore.Firestore;
let adminAuth: admin.auth.Auth;
let adminStorage: admin.storage.Storage;


function _tryInitWithServiceAccount(resolvedAdmin: any, serviceAccountJson: string): boolean {
  try {
    const serviceAccount = JSON.parse(serviceAccountJson);
    if (serviceAccount.private_key) {
      serviceAccount.private_key = serviceAccount.private_key.replace(/\\n/g, "\n");
    }
    resolvedAdmin.initializeApp({
      credential: resolvedAdmin.credential.cert(serviceAccount),
      storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET || "bkgalabovo2025.firebasestorage.app",
    });
    console.log("Firebase Admin SDK initialized using FIREBASE_SERVICE_ACCOUNT_JSON.");
    return true;
  } catch (parseError) {
    console.warn("WARNING: Failed to parse FIREBASE_SERVICE_ACCOUNT_JSON.", parseError);
    throw parseError;
  }
}

function _tryInitWithEnvVars(resolvedAdmin: any): boolean {
  if (process.env.FIREBASE_PRIVATE_KEY && process.env.FIREBASE_CLIENT_EMAIL) {
    const projectId = process.env.FIREBASE_PROJECT_ID || process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;
    resolvedAdmin.initializeApp({
      credential: resolvedAdmin.credential.cert({
        projectId: projectId,
        clientEmail: process.env.FIREBASE_CLIENT_EMAIL,
        privateKey: process.env.FIREBASE_PRIVATE_KEY.replace(/\\n/g, "\n"),
      }),
      storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET || "bkgalabovo2025.firebasestorage.app",
    });
    console.log("Firebase Admin SDK initialized using individual environment variables.");
    return true;
  }
  return false;
}

function _tryInitWithGoogleCreds(resolvedAdmin: any, googleCreds: string | undefined): boolean {
  if (googleCreds) {
    resolvedAdmin.initializeApp({
      credential: resolvedAdmin.credential.applicationDefault(),
    });
    console.log("Firebase Admin SDK initialized using GOOGLE_APPLICATION_CREDENTIALS.");
    return true;
  }
  return false;
}

function initializeFirebaseAdmin() {
  if (admin.apps && admin.apps.length > 0) {
    if (!adminDb) adminDb = admin.firestore();
    if (!adminAuth) adminAuth = admin.auth();
    if (!adminStorage) adminStorage = admin.storage();
    return;
  }

  const serviceAccountJson = process.env.FIREBASE_SERVICE_ACCOUNT_JSON;
  const googleCreds = process.env.GOOGLE_APPLICATION_CREDENTIALS;
  const resolvedAdmin: any = (admin as any).default || admin;

  try {
    let initialized = false;
    if (serviceAccountJson) {
      initialized = _tryInitWithServiceAccount(resolvedAdmin, serviceAccountJson);
    } else if (_tryInitWithEnvVars(resolvedAdmin)) {
      initialized = true;
    } else if (_tryInitWithGoogleCreds(resolvedAdmin, googleCreds)) {
      initialized = true;
    }

    if (!initialized) {
      console.warn("WARNING: Firebase Admin SDK credentials not found. Server-side Firebase Admin features will fail.");
      return;
    }

    adminDb = resolvedAdmin.firestore();
    adminAuth = resolvedAdmin.auth();
    adminStorage = resolvedAdmin.storage();
  } catch (error) {
    console.error("CRITICAL: Firebase Admin SDK initialization failed.", error);
  }
}

const getAdminDb = () => {
  if (!adminDb) {
    initializeFirebaseAdmin();
  }
  if (!adminDb) {
    throw new Error(
      "Firebase Admin Firestore is not initialized. Check your credentials."
    );
  }
  return adminDb;
};

const getAdminAuth = () => {
  if (!adminAuth) {
    initializeFirebaseAdmin();
  }
  if (!adminAuth) {
    throw new Error(
      "Firebase Admin Auth is not initialized. Check your credentials."
    );
  }
  return adminAuth;
};

const getAdminStorage = () => {
  if (!adminStorage) {
    initializeFirebaseAdmin();
  }
  if (!adminStorage) {
    throw new Error(
      "Firebase Admin Storage is not initialized. Check your credentials."
    );
  }
  return adminStorage;
};

export { getAdminDb, getAdminAuth, getAdminStorage };

